# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ALLAH\'IN GÜZEL İSİMLERİ (ESMÂ-İ HÜSNÂ)</text>\n  <rect x="35" y="60" width="190" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="90" text-anchor="middle" font-size="18" font-weight="bold" fill="#1d4ed8">el-HÂDÎ</text>\n  <text x="130" y="115" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">اَلْهَادِي</text>\n  <text x="130" y="145" text-anchor="middle" font-size="12" fill="#334155">Hidayet veren,</text>\n  <text x="130" y="165" text-anchor="middle" font-size="12" fill="#334155">doğru yola ulaştıran,</text>\n  <text x="130" y="185" text-anchor="middle" font-size="12" fill="#334155">yol gösterici olan.</text>\n  <text x="130" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">İlahi Rehber</text>\n  <rect x="255" y="60" width="190" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="90" text-anchor="middle" font-size="18" font-weight="bold" fill="#15803d">es-SELÂM</text>\n  <text x="350" y="115" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">اَلسَّلَامُ</text>\n  <text x="350" y="145" text-anchor="middle" font-size="12" fill="#334155">Esenlik veren,</text>\n  <text x="350" y="165" text-anchor="middle" font-size="12" fill="#334155">tehlikelerden kurtaran,</text>\n  <text x="350" y="185" text-anchor="middle" font-size="12" fill="#334155">barışın kaynağı olan.</text>\n  <text x="350" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">Huzur ve Güven</text>\n  <rect x="475" y="60" width="190" height="175" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="90" text-anchor="middle" font-size="18" font-weight="bold" fill="#a16207">el-VEKÎL</text>\n  <text x="570" y="115" text-anchor="middle" font-size="13" font-weight="bold" fill="#713f12">اَلْوَكِيلُ</text>\n  <text x="570" y="145" text-anchor="middle" font-size="12" fill="#334155">Güvenilip dayanılan,</text>\n  <text x="570" y="165" text-anchor="middle" font-size="12" fill="#334155">işleri en güzel şekilde</text>\n  <text x="570" y="185" text-anchor="middle" font-size="12" fill="#334155">sonuçlandıran.</text>\n  <text x="570" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#ca8a04">Tevekkül Kapısı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ESMÂ-İ HÜSNÂ\'NIN MÜSLÜMANIN HAYATINA YANSIMALARI</text>\n  <rect x="35" y="60" width="305" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="187" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">el-Hâdî ve es-Selâm Yansımaları</text>\n  <text x="50" y="115" font-size="11.5" fill="#334155">• el-Hâdî ismine inanan insan her namazda</text>\n  <text x="65" y="135" font-size="11" font-weight="bold" fill="#1e3a8a">"Bizi doğru yola ilet" (İhdinâ) diye dua eder.</text>\n  <text x="50" y="160" font-size="11.5" fill="#334155">• Başkalarına da iyiliği ve hakkı tavsiye eder.</text>\n  <text x="50" y="185" font-size="11.5" fill="#334155">• es-Selâm ismine sığınan kimse selamı yayar,</text>\n  <text x="65" y="205" font-size="11" fill="#475569">çevresine güven verir, kavgadan kaçınır.</text>\n  <rect x="360" y="60" width="305" height="175" rx="8" fill="#fefce8" stroke="#ca8a04"/>\n  <text x="512" y="85" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">el-Vekîl İsmi ve Tevekkül Bilinci</text>\n  <text x="375" y="115" font-size="11.5" fill="#334155">• Kul üzerine düşen bütün çabayı gösterir,</text>\n  <text x="390" y="135" font-size="11" fill="#475569">tedbirini alır (çalışır, araştırır).</text>\n  <text x="375" y="160" font-size="11.5" fill="#334155">• Ardından Yüce Allah\'a güvenip teslim olur.</text>\n  <text x="375" y="185" font-size="11.5" font-weight="bold" fill="#a16207">"Hasbünallâhu ve ni\'me\'l-vekîl"</text>\n  <text x="390" y="205" font-size="11" fill="#713f12">"Allah bize yeter, O ne güzel vekildir!"</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ALLAH\'A GÜVEN VE DUA ŞUURU</text>\n  <rect x="40" y="60" width="190" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="135" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Gayret Göstermek</text>\n  <text x="135" y="120" text-anchor="middle" font-size="11" fill="#334155">Tembellik yapmadan</text>\n  <text x="135" y="140" text-anchor="middle" font-size="11" fill="#334155">dersine çalışmak,</text>\n  <text x="135" y="160" text-anchor="middle" font-size="11" fill="#334155">hastalıkta doktora gitmek,</text>\n  <text x="135" y="180" text-anchor="middle" font-size="11" fill="#334155">sebeplere sarılmak.</text>\n  <text x="135" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Fiili Dua</text>\n  <rect x="255" y="60" width="190" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Dua ile İstemek</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" fill="#334155">Hâdî isminden hidayet,</text>\n  <text x="350" y="140" text-anchor="middle" font-size="11" fill="#334155">Selâm isminden esenlik,</text>\n  <text x="350" y="160" text-anchor="middle" font-size="11" fill="#334155">Vekîl isminden yardım</text>\n  <text x="350" y="180" text-anchor="middle" font-size="11" fill="#334155">ve başarı dilemek.</text>\n  <text x="350" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">Sözlü Dua</text>\n  <rect x="470" y="60" width="190" height="175" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="565" y="88" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Tevekkül ve Huzur</text>\n  <text x="565" y="120" text-anchor="middle" font-size="11" fill="#334155">Sonucu Yüce Allah\'a</text>\n  <text x="565" y="140" text-anchor="middle" font-size="11" fill="#334155">bırakıp endişeden</text>\n  <text x="565" y="160" text-anchor="middle" font-size="11" fill="#334155">kurtulmak, O\'nun</text>\n  <text x="565" y="180" text-anchor="middle" font-size="11" fill="#334155">takdirine razı olmak.</text>\n  <text x="565" y="210" text-anchor="middle" font-size="11" font-weight="bold" fill="#ca8a04">Gönül Rahatlığı</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
